package com.yuegang.zhihui.ai.application;import com.yuegang.zhihui.ai.api.*;import com.yuegang.zhihui.common.core.*;import java.time.*;import java.util.*;import javax.sql.*;import org.springframework.jdbc.core.*;import org.springframework.transaction.annotation.*;
public class AiGovernanceService{private static final String DEFAULT="你是跨境智汇企业客服。只能依据提供的已审核资料和系统提供的只读工具结果回答；必须标注引用；资料不足时明确拒答；不得生成SQL、修改订单、调整余额或发布知识。";private final JdbcTemplate jdbc;public AiGovernanceService(DataSource d){jdbc=new JdbcTemplate(d);}public String activeSystemPrompt(){return jdbc.query("SELECT system_prompt FROM ai_prompt_config WHERE enabled=TRUE ORDER BY updated_at DESC LIMIT 1",r->r.next()?r.getString(1):DEFAULT);}public List<PromptConfigView>prompts(){return jdbc.query("SELECT id,code,system_prompt,model_name,temperature,knowledge_scope,sensitive_words,enabled,version,updated_at FROM ai_prompt_config ORDER BY updated_at DESC",(r,n)->prompt(r));}@Transactional public PromptConfigView save(SavePromptConfigRequest c,long operator){long id=next();if(c.enabled())jdbc.update("UPDATE ai_prompt_config SET enabled=FALSE WHERE enabled=TRUE");int n=c.version()==0?jdbc.update("INSERT INTO ai_prompt_config(id,code,system_prompt,model_name,temperature,knowledge_scope,sensitive_words,enabled,updated_by) VALUES(?,?,?,?,?,?,?,?,?)",id,c.code(),c.systemPrompt(),c.modelName(),c.temperature(),c.knowledgeScope(),c.sensitiveWords(),c.enabled(),operator):jdbc.update("UPDATE ai_prompt_config SET system_prompt=?,model_name=?,temperature=?,knowledge_scope=?,sensitive_words=?,enabled=?,updated_by=?,version=version+1 WHERE code=? AND version=?",c.systemPrompt(),c.modelName(),c.temperature(),c.knowledgeScope(),c.sensitiveWords(),c.enabled(),operator,c.code(),c.version());if(n!=1)throw new BusinessException(ErrorCode.BUSINESS_CONFLICT);return jdbc.query("SELECT id,code,system_prompt,model_name,temperature,knowledge_scope,sensitive_words,enabled,version,updated_at FROM ai_prompt_config WHERE code=?",r->{r.next();return prompt(r);},c.code());}public List<EvaluationCaseView>cases(){return jdbc.query("SELECT id,category,question,expected_evidence,forbidden_answer,expected_refusal,enabled FROM ai_evaluation_case ORDER BY category,created_at",(r,n)->evaluationCase(r));}public EvaluationCaseView addCase(SaveEvaluationCaseRequest c,long operator){long id=next();jdbc.update("INSERT INTO ai_evaluation_case(id,category,question,expected_evidence,forbidden_answer,expected_refusal,enabled,created_by) VALUES(?,?,?,?,?,?,?,?)",id,c.category(),c.question(),c.expectedEvidence(),c.forbiddenAnswer(),c.expectedRefusal(),c.enabled(),operator);return evaluationCase(id);}public EvaluationCaseView setCaseEnabled(String value,boolean enabled){long id=id(value);if(jdbc.update("UPDATE ai_evaluation_case SET enabled=? WHERE id=?",enabled,id)!=1)throw new BusinessException(ErrorCode.RESOURCE_NOT_FOUND);return evaluationCase(id);}private EvaluationCaseView evaluationCase(long id){return jdbc.query("SELECT id,category,question,expected_evidence,forbidden_answer,expected_refusal,enabled FROM ai_evaluation_case WHERE id=?",r->{if(!r.next())throw new BusinessException(ErrorCode.RESOURCE_NOT_FOUND);return evaluationCase(r);},id);}private static EvaluationCaseView evaluationCase(java.sql.ResultSet r)throws java.sql.SQLException{return new EvaluationCaseView(Long.toString(r.getLong(1)),r.getString(2),r.getString(3),r.getString(4),r.getString(5),r.getBoolean(6),r.getBoolean(7));}private static PromptConfigView prompt(java.sql.ResultSet r)throws java.sql.SQLException{return new PromptConfigView(Long.toString(r.getLong(1)),r.getString(2),r.getString(3),r.getString(4),r.getDouble(5),r.getString(6),r.getString(7),r.getBoolean(8),r.getLong(9),r.getTimestamp(10).toLocalDateTime().atOffset(ZoneOffset.UTC));}private static long id(String value){try{long id=Long.parseLong(value);if(id<=0)throw new NumberFormatException();return id;}catch(Exception e){throw new BusinessException(ErrorCode.VALIDATION_ERROR);}}private static long next(){return UUID.randomUUID().getMostSignificantBits()&Long.MAX_VALUE;}}
